'use strict';
const $=s=>document.querySelector(s),storage='publisher-rescue-v2';
const fresh=()=>({started:false,intro:false,room:'office',docs:[],visited:[],parcel:'none',poet:false,cat:'none',ribbon:false,ending:null,feedback:[],epilogue:0,historySeen:false,draft:{selected:[],evidence:{}}});
let state=fresh();try{let saved=JSON.parse(localStorage.getItem(storage));if(saved&&Array.isArray(saved.docs))state={...state,...saved,draft:{...state.draft,...saved.draft}}}catch{}
let room=rooms[state.room]?state.room:'office',player={x:430,y:440},route=[],onArrival=null,tick=0,sound=false,audioContext=null,lastStep=0,modal=false,lockedModal=false,focusBefore=null;
const save=()=>{try{localStorage.setItem(storage,JSON.stringify(state))}catch{}updateUI()};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),2700)}
function open(html,locked=false){if(!modal)focusBefore=document.activeElement;route=[];onArrival=null;modal=true;lockedModal=locked;$('#overlay').hidden=false;$('#panel').innerHTML=html;document.body.style.overflow='hidden';$('#game').inert=true;$('#panel').scrollTop=0;$('#panel').querySelector('button,input')?.focus({preventScroll:true})}
function close(){if(lockedModal)return;modal=false;$('#overlay').hidden=true;document.body.style.overflow='';$('#game').inert=false;if(focusBefore?.isConnected)focusBefore.focus({preventScroll:true})}
function shell(title,kicker,body,buttons,locked=false){open(`${locked?'':'<button class="close" aria-label="Закрыть окно">×</button>'}<div class="kicker">${kicker}</div><h2 id="panelTitle">${title}</h2>${body}<div class="actions">${buttons.map((b,i)=>`<button class="btn ${b[2]||''}" data-action="${i}">${b[0]}</button>`).join('')}</div>`,locked);if($('.close'))$('.close').onclick=close;buttons.forEach((b,i)=>$(`[data-action="${i}"]`).onclick=b[1])}
function dialogue(who,job,lines,buttons,locked=false){let n=0;function show(){shell(who,job,`<div class="who"><canvas class="portrait" width="58" height="64" aria-hidden="true"></canvas><small>${job}<br>${n+1} / ${lines.length}</small></div><p>${lines[n]}</p>`,n<lines.length-1?[['Дальше',()=>{n++;show()},'primary']]:buttons||[['Закончить разговор',close,'primary']],locked);const pc=$('.portrait').getContext('2d');pc.translate(29,57);pc.scale(.78,.78);person(pc,0,0,who==='Карамзин'?'#405565':who==='Агафон'?'#86664a':who==='Софья Павловна'?'#9d6e65':'#667b55',false,0)}show()}
function welcome(){open(`<div class="welcome-art"></div><div class="kicker">ПРИКЛЮЧЕНИЕ О КАРАМЗИНЕ</div><h2 id="panelTitle">Дело издателя</h2><p>Карамзина увозят. У вас остаются ключ от редакции и несколько часов, чтобы собрать бумаги в его защиту.</p><p>Исследуйте город, разговаривайте с людьми, делайте выписки. В конце вам предстоит решить, что включить в записку.</p><div class="notice"><b>Условие игры:</b> арест Карамзина вымышлен. В действительности в 1792 году арестовали Новикова. Исторические сведения о журналах отделены от придуманного приключения.</div><div class="actions"><button class="btn primary" id="start">${state.started?'Продолжить':'Начать историю'} →</button><button class="btn subtle" id="how">Как играть</button></div>`,true);$('#start').onclick=()=>{state.started=true;save();lockedModal=false;close();if(!state.intro)departure();else if(state.ending&&(!state.historySeen||state.epilogue<2))continueStory()};$('#how').onclick=help}
function help(){shell('Как играть','ПРОГУЛКА ПО ГОРОДУ','<p>Нажмите на дорожку, чтобы пойти. Нажмите на человека или предмет — персонаж подойдёт сам. На компьютере работают и стрелки / WASD.</p><p>Кнопка «Карта» показывает места и оставшиеся зацепки. Все выписки сохраняются в «Записях». Записку можно готовить за столом в редакции.</p><p>Сюжет торопит героя, но настоящего таймера нет. Можно спокойно читать и заниматься необязательными делами.</p><p class="small">Прогресс хранится только в этом браузере. Новая версия начинает отдельное прохождение, не удаляя старую пробную главу.</p>',[['Вернуться',()=>{close();if(!state.started)welcome()},'primary'],['Начать заново',reset]])}
function reset(){shell('Начать заново?','НОВОЕ ПРОХОЖДЕНИЕ','<p>Будут очищены только записи и результат этой версии на вашем устройстве.</p>',[['Начать заново',()=>{state=fresh();room='office';player={x:430,y:440};save();renderSpots();welcome()},'primary'],['Оставить прохождение',close]])}
function departure(){dialogue('Карамзин','У двери уже ждут',['За мной пришли. Времени почти нет. Возьмите ключ от кабинета. Там мои бумаги.','Найдите всё, что поможет меня оправдать. Мои рукописи, письма, людей, которые знают, чем я занимался. Составьте записку и передайте её вместе с бумагами.','У Агафона в лавке хранится объявление о журнале. В типографии спросите Варвару. А Софья Павловна знает моих читателей. Начните с них.'],[['Взять ключ',()=>{state.intro=true;save();renderSpots();shell('Колёса за окном','НАЧАЛО РАССЛЕДОВАНИЯ','<p>Дверь закрывается. С улицы слышно, как отъезжает экипаж. На столе осталась незаконченная корректура.</p><p>Вы разворачиваете чистый лист. Пока писать нечего.</p>',[['Осмотреть кабинет',()=>{lockedModal=false;close()},'primary']],true)},'primary']],true)}
function inspect(id,onDone){const d=docs[id],isnew=!state.docs.includes(id);shell(d.title,d.tag,`<p>${d.text}</p><div class="paper">${d.body}${d.quote?`<p>${d.quote}</p>`:''}</div><p>${d.note}</p><details class="source"><summary>Источник и граница вымысла</summary><p>${d.source}</p></details>`,[[isnew?'Сделать выписку':'Закрыть документ',()=>{if(isnew){state.docs.push(id);save();renderSpots();toast('Сохранено: '+d.title)}if(onDone)onDone();else close()},'primary']])}
function notebook(){shell('Записи и находки','ВАША СУМКА',`${state.docs.length?'<div class="doclist">'+state.docs.map(id=>`<button class="doccard" data-doc="${id}">${docs[id].title}<small>${docs[id].tag}</small></button>`).join('')+'</div>':'<p>Пока пусто. Осмотрите книги и папки в редакции.</p>'}${state.parcel==='carried'?'<div class="notice">Свёрток для Софьи Павловны. Адрес — гостиная на карте.</div>':''}${state.parcel==='returned'?'<div class="notice">Свёрток доставлен. Софья Павловна получила свои книги.</div>':''}${state.ribbon?'<div class="notice">Шёлковая лента: вы нашли её под креслом.</div>':''}`, [['Закрыть записи',close,'primary']]);document.querySelectorAll('[data-doc]').forEach(b=>b.onclick=()=>inspect(b.dataset.doc))}
function assignment(){let missing=REQUIRED.filter(id=>!state.docs.includes(id));shell('Собрать защиту','ПОРУЧЕНИЕ КАРАМЗИНА','<p>Выясните, что известно о его работе, путешествии, журнале и читателях. Не всё найденное станет доказательством.</p><p>Оставьте место в записке для конкретных свидетельств. Читательская любовь сама по себе не снимает подозрений.</p><div class="notice">'+(missing.length?'Осталось изучить: '+missing.map(id=>docs[id].title).join('; ')+'.':'Все основные материалы собраны. Можно закончить записку.')+'</div>',[['Открыть карту',map,'primary'],['Вернуться',close]])}
function map(){shell('Где искать','КАРТА ГОРОДА',`<div class="map-grid">${Object.entries(rooms).map(([id,r])=>{let ids=REQUIRED.filter(d=>docs[d].room===id),n=ids.filter(d=>state.docs.includes(d)).length;return `<button class="doccard" data-map="${id}"><strong>${r.title}</strong><small>${ids.length?n+' / '+ids.length+' материалов':state.poet?'Митя ждёт новостей':'Здесь можно поговорить с Митей'}</small></button>`}).join('')}</div><p class="small">Лавка, типография и гостиная — игровые адреса, не точная карта исторической Москвы.</p>`,[['Вернуться',close]]);document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>go(b.dataset.map))}
function interact(id){if(id==='out')return go('street');if(rooms[id])return go(id);if(docs[id])return inspect(id);if(id==='map')return map();if(id==='departure'){if(!state.intro)return departure();if(state.ending==='rescued')return dialogue('Карамзин','Снова в редакции',['Бумаги оставьте у меня. Я ещё перечитаю вашу записку. Спасибо, что не бросили это дело.']);return shell('Пустое место у окна','РЕДАКЦИЯ','<p>Карамзина здесь нет. На подоконнике лежат очки. Вы оставляете их на столе рядом с рукописями.</p>',[['Продолжить поиски',close,'primary']])}if(id==='desk')return desk();if(id==='clerk')return clerk();if(id==='poet')return poet();if(id==='printer')return printer();if(id==='host')return host();if(id==='walker')return walker();if(id==='cat')return cat();if(id==='ribbon')return ribbon();if(id==='bench')return shell('На скамье','МОЖНО ПЕРЕВЕСТИ ДУХ','<p>Из города доносится колокольный звон. Вы садитесь на минуту и проверяете, всё ли на месте в сумке.</p><p>Никто не торопит вас перелистывать бумаги. Можно ещё раз спокойно их прочесть.</p>',[['Посмотреть записи',notebook,'primary'],['Встать и идти дальше',close]])}
function clerk(){let text=state.parcel==='returned'?'Книги доставили? Благодарю. Объявление и журналы я оставил на прилавке, если понадобится ещё посмотреть.':'Карамзина увезли? Сегодня? Погодите… Объявление у меня есть. Храню старые подписные листы вместе со счетами. Сейчас достану.';let b=[['Посмотреть объявление',()=>inspect('program'),'primary'],['Есть книжки с рецензиями?',()=>inspect('reviews')]];if(state.parcel==='none')b.push(['Что за свёрток?',()=>dialogue('Агафон','Книгопродавец',['Книги Софье Павловне. Она просила прислать, а посыльный до сих пор не вернулся. Если всё равно к ней пойдёте, отнесёте?'],[['Взять с собой',()=>{state.parcel='carried';save();close();toast('Свёрток для Софьи Павловны — в сумке')},'primary'],['Лучше дождитесь посыльного',()=>{state.parcel='left';save();close()}]])]);b.push(['Мне пора',close]);dialogue('Агафон','Книгопродавец',[text],b)}
function poet(){if(!state.poet)return dialogue('Митя','Молодой автор',['Я к Николаю Михайловичу. Оставил ему стихи на прошлой неделе. Не знаете, он дома?'],[['Его увезли. Я собираю бумаги в защиту.',()=>{state.poet=true;save();dialogue('Митя','Молодой автор',['Вот как… Я не знал. Конечно, сейчас не до моих стихов.','Если нужно что-нибудь отнести, я здесь побуду. До вечера никуда не уйду.'],[['Спасибо. Возможно, понадобится.',close,'primary'],['А стихи при вас?',poem]])},'primary']]);dialogue('Митя','Ждёт новостей',[state.ending==='rescued'?'Вернулся? Слава богу. С рукописью я потом зайду. Через несколько дней.':state.ending?'Что ответили? Если нужны ещё бумаги, я помогу отнести.':'Есть новости? Я пока здесь. Если понадобится посыльный, не ищите другого.'],[['Послушать его стихи',poem],['Пока ничего не нужно',close]])}
function poem(){dialogue('Митя','Небольшое отступление',['Только не смейтесь. Я ещё не закончил.','«В окне погас последний свет…» Дальше было про соловья. Но сейчас декабрь, и мне сказали, что соловья лучше убрать.','Вы правы, сейчас неподходящее время. Уберу листы.'],[['Пусть останется до лета',()=>{toast('Митя прячет листы в карман');close()},'primary'],['Можно обойтись без соловья',()=>{toast('Митя кивает и делает пометку');close()}]])}
function printer(){dialogue('Варвара','В типографии',['С утра его ждали с корректурой. Потом мальчик прибежал, сказал, что увезли. Сами-то вы видели?','Вот листы с его поправками. Он и шрифты выбирает, и с типографией договаривается. Если нужно подтвердить, как работает, покажите эти листы.'],[['Рассмотреть корректуры',()=>inspect('work'),'primary'],['У вас кот на бумагах',cat],['Спасибо, я ещё зайду',close]])}
function host(){if(state.parcel==='carried')return dialogue('Софья Павловна','В гостиной',['От Агафона? Положите сюда. Спасибо, что принесли. Я сама хотела заехать, но так и не выбралась.'],[['Отдать книги',()=>{state.parcel='returned';save();host()},'primary']]);dialogue('Софья Павловна','В гостиной',['Мне уже передали про Николая Михайловича. Что вам нужно — письма, журналы? Посмотрите, я всё оставила на столе.','Если ищете людей, которые его читают, поговорите ещё с Анной. Она ушла к Симонову монастырю. После «Бедной Лизы» всё собиралась туда добраться.'],[['Поговорить о чтении',()=>inspect('readers'),'primary'],['Посмотреть выписку о языке',()=>inspect('language')],...(state.ribbon?[['Не ваша ли лента?',()=>{state.ribbon=false;state.ribbonReturned=true;save();dialogue('Софья Павловна','В гостиной',['Моя. Вчера искали всем домом — и под стол заглядывали, и за диван. А она под креслом. Спасибо.'])}]]:[]),['Продолжить поиски',close]])}
function walker(){dialogue('Анна','Читательница',['От Софьи Павловны? Да, я сказала ей, куда иду. Что случилось?'],[['Рассказать о Карамзине',()=>dialogue('Анна','Читательница',['Неужели… А я его повесть с собой взяла. Хотела посмотреть, как здесь всё на самом деле.','Но я ведь с ним даже не знакома. О его делах ничего не знаю. Только книги читала. Посмотрите, если это вам нужно.'],[['Посмотреть книгу',()=>inspect('lisa'),'primary']]),'primary']])}
function cat(){if(state.cat!=='none')return shell(state.cat==='string'?'Кот устроился у печки':'Кот на подоконнике','ТИПОГРАФИЯ',`<p>${state.cat==='string'?'На полку с бумагами он больше не возвращается. Варвара наконец забрала нужные листы.':'Он смотрит на вас и медленно отворачивается. Варвара стряхивает шерсть с листа.'}</p>`,[['Не мешать',close,'primary']]);shell('На тёплой бумаге','НЕОБЯЗАТЕЛЬНОЕ ДЕЛО','<p>Кот лежит поперёк стопки. Варвара пробует вытянуть нижний лист, но кот придерживает его лапой.</p><p>Рядом со столом валяется обрезок бечёвки от упаковки.</p>',[['Отвлечь бечёвкой',()=>{state.cat='string';save();shell('Сработало','ТИПОГРАФИЯ','<p>Кот сначала следит одними глазами, потом прыгает за бечёвкой. Варвара убирает стопку на верхнюю полку.</p><p>— Спасибо. Теперь хоть до листов добраться можно.</p>',[['Погладить кота и вернуться к делу',close,'primary']])},'primary'],['Попробовать снять его со стопки',()=>{state.cat='window';save();shell('Место занято','ТИПОГРАФИЯ','<p>Кот выскальзывает из рук и забирается на подоконник. Кажется, оставаться на бумагах ему уже не хотелось — уходить по чужой просьбе тоже.</p>',[['Оставить его в покое',close,'primary']])}]],false)}
function ribbon(){if(state.ribbon||state.ribbonReturned)return shell('Под креслом','ГОСТИНАЯ','<p>Больше ничего нет. Только пыль и ножка кресла, которую давно пора подклеить.</p>',[['Отойти',close]]);shell('Лента','ПОД КРЕСЛОМ','<p>За ножку зацепилась шёлковая лента. На бумаги Карамзина не похоже.</p>',[['Поднять и спросить хозяйку',()=>{state.ribbon=true;save();close();toast('Лента в сумке')},'primary'],['Оставить на месте',close]])}
function desk(){if(!state.intro)return departure();if(state.ending)return ending();compose()}
function compose(){const n=state.draft.selected.length;shell('Записка в защиту Карамзина','ВЫБЕРИТЕ 3–5 ДОВОДОВ',`<p>Что вы готовы утверждать? Для каждого выбранного довода приложите подходящую выписку. Остальные находки останутся в сумке.</p><p class="small">Сохранено автоматически. Можно уйти за бумагами и вернуться.</p><div id="draftClaims">${claims.map(c=>`<div class="claimbox"><label class="choice"><input type="checkbox" name="claim" value="${c.id}" ${state.draft.selected.includes(c.id)?'checked':''}><span><b>${c.title}</b><br>${c.text}</span></label>${state.draft.selected.includes(c.id)?`<label class="attach">Приложение<select data-evidence="${c.id}"><option value="">Пока без приложения</option>${state.docs.filter(id=>docs[id].room).map(id=>`<option value="${id}" ${state.draft.evidence[c.id]===id?'selected':''}>${docs[id].title}</option>`).join('')}</select></label>`:''}</div>`).join('')}</div><p class="small">Выбрано доводов: ${n}. Собрано материалов: ${REQUIRED.filter(id=>state.docs.includes(id)).length} / ${REQUIRED.length}.</p>`,[['Перечитать записку',previewDraft,'primary'],['Вернуться за материалами',map]]);document.querySelectorAll('input[name=claim]').forEach(i=>i.onchange=()=>{if(i.checked&&state.draft.selected.length>=5){i.checked=false;return toast('Не больше пяти доводов: выберите главное')}if(i.checked)state.draft.selected.push(i.value);else state.draft.selected=state.draft.selected.filter(x=>x!==i.value);save();let scroll=$('#panel').scrollTop;compose();$('#panel').scrollTop=scroll});document.querySelectorAll('[data-evidence]').forEach(s=>s.onchange=()=>{state.draft.evidence[s.dataset.evidence]=s.value;save()})}
function previewDraft(){if(state.draft.selected.length<3)return toast('Выберите хотя бы три довода');const missing=REQUIRED.filter(id=>!state.docs.includes(id));if(missing.length)return shell('Остались непроверенные материалы','ПЕРЕД ОТПРАВКОЙ',`<p>Черновик сохранён. Прежде чем отправлять его, закончите осмотр: ещё не всё прочитано.</p><div class="doclist">${missing.map(id=>`<button class="doccard" data-missing="${docs[id].room}">${docs[id].title}<small>${rooms[docs[id].room].title}</small></button>`).join('')}</div>`,[['Вернуться к черновику',compose]]) , document.querySelectorAll('[data-missing]').forEach(b=>b.onclick=()=>go(b.dataset.missing));let d=state.draft;shell('Передать записку','ПОСЛЕДНИЙ ПРОСМОТР',`<div class="paper">${d.selected.map(id=>{let c=claims.find(c=>c.id===id),e=d.evidence[id];return `<p>${c.text}</p><small>Приложение: ${e?docs[e].title:'не выбрано'}.</small>`}).join('')}</div><p>${state.poet?'Митя ждёт у редакции. Он отнесёт запечатанный пакет.':'Вы отнесёте запечатанный пакет сами.'} После этого останется ждать ответа.</p>`,[['Запечатать и отправить',evaluateDraft,'primary'],['Исправить записку',compose]])}
function grade(d){const areas=new Set(),feedback=[];let bad=0,unsupported=0;for(const id of d.selected){const c=claims.find(x=>x.id===id);if(!c)continue;const e=d.evidence[id];if(c.area==='error'){bad++;feedback.push(id==='break'?'Утверждение о полном разрыве противоречит прежнему сотрудничеству и сохранению просветительской цели. Новая программа не доказывает разрыв всех связей.':'Читательская любовь и особенности слога не позволяют отвергнуть все подозрения. В записке сделан вывод, для которого нет свидетельства.');continue}if(!c.supports.includes(e)){unsupported++;feedback.push('«'+c.title+'»: '+(e?'приложенный материал не подтверждает этот довод.':'не приложено подтверждение.'));continue}areas.add(c.area)}const missing=['travel','program','work'].filter(a=>!areas.has(a));for(const a of missing)feedback.push({travel:'Не подтверждён частный характер европейского путешествия.',program:'Не объяснено отличие программы нового журнала.',work:'Не показано, в чём состояла известная литературная и издательская работа Карамзина.'}[a]);const kind=bad?'denied':missing.length||unsupported?'delayed':'rescued';if(kind==='rescued')feedback.push('Вы ответили на подозрение о поездке, объяснили программу и описали работу издателя. Формулировки не выходят за пределы приложенных материалов.');return {kind,feedback}}
function evaluateDraft(){const r=grade(state.draft);state.ending=r.kind;state.feedback=r.feedback;state.historySeen=false;state.epilogue=0;save();shell('Пакет передан','ВЕЧЕР',`<p>${state.poet?'Митя прячет пакет под полой и уходит. Через некоторое время возвращается: «Приняли. Велели утром зайти».':'Вы оставляете пакет в канцелярии. Писарь проверяет число приложений и велит прийти за ответом утром.'}</p><p>В редакции гаснут свечи. Вы остаётесь ждать.</p>`,[['Наступает утро',()=>{renderSpots();ending()},'primary']],true)}
function sideEnd(){let s=[];if(state.parcel==='returned')s.push('Софья Павловна получила книги. Услышав новости, она просит передать ей, не нужна ли ещё помощь.');else if(state.parcel==='carried')s.push('Книги Софьи Павловны всё ещё у вас. Свёрток можно отнести, когда вернётесь в город.');if(state.cat==='string')s.push('В типографии кот спит у печки; Варвара работает за свободным столом.');else if(state.cat==='window')s.push('Кот занял подоконник и наблюдает за типографией оттуда.');if(state.ribbonReturned)s.push('Лента снова у хозяйки. Она повязала ею книгу, чтобы не потерять закладку.');return s.length?'<div class="notice">'+s.join('<br><br>')+'</div>':''}
function ending(){const r={rescued:['Он вернулся','Карамзин входит без стука. Снимает пальто, кладёт на стол вашу записку.','— Отпустили. О поездке спрашивали отдельно. Хорошо, что вы не забыли приложить сведения.','В этой вымышленной истории ваши материалы помогли добиться освобождения.','✓'],delayed:['Ответа пока нет','Утром вам возвращают часть пакета. В записке писаря перечислено, какие сведения нужно уточнить.','Карамзин остаётся под стражей. Вы нашли материалы, но не связали их с главными доводами защиты.','Можно вернуться к черновику и отправить более убедительную записку.','↺'],denied:['Записка не помогла','Пакет возвращают с пометами. Некоторые утверждения сочли недостоверными или не подтверждёнными приложениями.','Карамзина не отпускают. Обещав помочь, вы передали защиту, которая не выдержала проверки.','Это проигрыш текущей попытки. Исправить её можно после исторического эпилога.','—']}[state.ending];shell(r[0],'ИГРОВОЙ ФИНАЛ · ВЫМЫШЛЕННЫЕ СОБЫТИЯ',`<div class="ending">${r[4]}</div><p>${r[1]}</p><p>${r[2]}</p><p class="small">${r[3]}</p><details class="source"><summary>Почему получился этот исход</summary>${state.feedback.map(t=>`<p>${t}</p>`).join('')}</details>${sideEnd()}<div class="notice">В действительности Карамзина не арестовывали и такая записка его не освобождала. Дальше — реальная история.</div>`,[['Что произошло в действительности',history,'primary']],true)}
function history(){state.historySeen=true;save();shell('Что было на самом деле','ИСТОРИЧЕСКИЙ ЭПИЛОГ','<p>В 1792 году арестовали <b>Николая Новикова</b>. Он оставался в заключении до 1796 года. Арест Карамзина, поручение помощнику и все три игровых исхода придуманы.</p><p>Карамзин действительно оказался под подозрением в связи с европейским путешествием. По Лотману, свидетельства допрошенных о том, что он ездил самостоятельно и на свои средства, помогли ему избежать репрессий, хотя подозрения сохранились.</p><p>«Московский журнал» выходил с января 1791 по декабрь 1792 года. Его история не заканчивается нашим игровым освобождением: это разные события.</p><p>После журнала Карамзин выпускал «Аглаю» (1794–1795), затем «Аониды» (1796–1799). Посмотрим, как продолжилось его дело.</p><p class="source">Западов: разделы об изданиях Новикова и «Московском журнале». Лотман: «Сотворение Карамзина», 1987, с. 81. Вывод о литературных достоинствах не равен доказательству политической невиновности.</p>',[['1796–1799. Открыть «Аониды»',()=>epilogue(0),'primary']],true)}
function epilogue(n){const id=n===0?'aonides':'makarov';inspect(id,()=>{state.epilogue=Math.max(state.epilogue,n+1);save();if(n===0){shell('Прошло ещё несколько лет','1803 ГОД','<p>Сформировавшаяся читательская публика хочет не только новых произведений, но и совета: какие книги выбирать?</p><p>На это по-своему отвечает критик Пётр Макаров.</p>',[['Открыть «Московский Меркурий»',()=>epilogue(1),'primary']],true)}else finish()});lockedModal=true;$('.close')?.remove();$('#panel').querySelector('button')?.focus({preventScroll:true})}
function finish(){shell('История завершена','ЗАПИСКА, НАХОДКИ И ПОСЛЕДСТВИЯ',`<p>Вы ${state.ending==='rescued'?'добились освобождения Карамзина в вымышленном сюжете':state.ending==='delayed'?'получили просьбу дополнить защиту':'не смогли убедить адресата записки'}. Исторический эпилог показал, что произошло в действительности.</p><p>Все выписки сохранены. В них есть и сведения, которые не понадобились для защиты.</p><div class="notice">Итоговый тест проходит отдельно, после игры. Здесь его вопросов нет.</div>${sideEnd()}`, [['Перечитать находки',notebook,'primary'],['Пересмотреть записку',()=>{state.ending=null;save();renderSpots();compose()}],['Вернуться в город',()=>{lockedModal=false;close()}],['Начать с начала',reset]])}
function continueStory(){if(!state.historySeen)return history();if(state.epilogue<2)return epilogue(state.epilogue);finish()}
function go(id){if(!state.intro)return departure();close();room=id;state.room=id;player={x:id==='street'?420:700,y:445};route=[];onArrival=null;if(!state.visited.includes(id))state.visited.push(id);save();renderSpots()}
function updateUI(){$('#count').textContent=state.docs.length;$('#place').textContent=rooms[room].title;$('#chapter').textContent=rooms[room].sub+' · 1792';const n=REQUIRED.filter(id=>state.docs.includes(id)).length;$('#questText').textContent=!state.intro?'У двери ждут. Поговорите с Карамзиным.':state.ending?(state.epilogue<2?'После финала: узнайте, как продолжилась реальная история.':'История завершена. Записи и город остаются доступны.'):`Соберите материалы, чтобы добиться освобождения Карамзина. Изучено: ${n} / ${REQUIRED.length}.`;$('#travel').innerHTML=`<button id="mapButton">Карта · 6 мест</button><button id="backOffice" class="${room==='office'?'current':''}">В редакцию</button>${state.ending?'<button id="continueEnding">Эпилог</button>':''}`;$('#mapButton').onclick=()=>state.intro?map():departure();$('#backOffice').onclick=()=>go('office');if($('#continueEnding'))$('#continueEnding').onclick=continueStory}
